<div class="section-head"><div><p class="eyebrow">ADMINISTRATION</p><h1>Kitchen crew</h1></div><span><?=count($users)?> people</span></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Joined</th><th>Role</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><b><?=e($u['name'])?></b></td><td><?=e($u['email'])?></td><td><?=date('M j, Y',strtotime($u['created_at']))?></td><td><?php if($u['role']==='superadmin'):?><span class="badge">Superadmin</span><?php elseif((int)$u['id']===(int)$current['id']):?><span class="badge"><?=e($u['role'])?></span><?php else:?><form method="post" action="/admin/users/<?=$u['id']?>/role" class="inline"><?=csrf()?><select name="role"><option value="user" <?=$u['role']==='user'?'selected':''?>>User</option><option value="admin" <?=$u['role']==='admin'?'selected':''?>>Web Admin</option></select><button class="small">Save</button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div>
